import { MakeLogicType, actions, kea, path, reducers } from 'kea'

import { TaxonomicFilterGroupType } from 'lib/components/TaxonomicFilter/types'
import { getCurrentTeamIdOrNone, getCurrentUserIdOrNone } from 'lib/utils/getAppContext'

const lastTabPersistenceConfig = {
    persist: true,
    prefix: `${getCurrentUserIdOrNone() ?? 'anonymous'}__${getCurrentTeamIdOrNone() ?? 'unknown'}__`,
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taxonomicFilterLastTabLogicValues {
    lastTabByKey: Record<string, TaxonomicFilterGroupType>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taxonomicFilterLastTabLogicActions {
    rememberLastTab: (
        key: string,
        groupType: TaxonomicFilterGroupType
    ) => {
        key: string
        groupType: TaxonomicFilterGroupType
    }
}

export type taxonomicFilterLastTabLogicType = MakeLogicType<
    taxonomicFilterLastTabLogicValues,
    taxonomicFilterLastTabLogicActions
>

/** Remembers the tab a person last chose, per picker, so the picker reopens on it. */
export const taxonomicFilterLastTabLogic = kea<taxonomicFilterLastTabLogicType>([
    path(['lib', 'components', 'TaxonomicFilter', 'taxonomicFilterLastTabLogic']),
    actions({
        rememberLastTab: (key: string, groupType: TaxonomicFilterGroupType) => ({ key, groupType }),
    }),
    reducers({
        lastTabByKey: [
            {} as Record<string, TaxonomicFilterGroupType>,
            lastTabPersistenceConfig,
            {
                rememberLastTab: (state, { key, groupType }) => ({ ...state, [key]: groupType }),
            },
        ],
    }),
])
